for _ in $(seq 1 30); do
  [[ -n "$(kubectl get csr "${Q1_USER_NAME}" -o jsonpath='{.status.certificate}')" ]] && break
  sleep 1
done
kubectl get csr "${Q1_USER_NAME}" -o jsonpath='{.status.certificate}' | base64 -d > "$d/user.crt"
